sys.path.insert(0, '/root/.venv/lib/python3.12/site-packages')
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

in_path = '/root/data/workbook.xlsx'
out_dir = '/root/output'
os.makedirs(out_dir, exist_ok=True)

wb = load_workbook(in_path, data_only=False)
print('Sheets:', wb.sheetnames)
ws_task = wb['Task']
ws_data = wb['Data']

def print_range(ws, min_row, max_row, min_col, max_col, title=None):
    if title:
        print('\n' + title)
    for r in range(min_row, max_row+1):
        parts = []
        for c in range(min_col, max_col+1):
            coord = f'{get_column_letter(c)}{r}'
            v = ws.cell(r,c).value
            sv = v
            if isinstance(sv, str) and len(sv) > 40:
                sv = sv[:37] + '...'
            parts.append(f'{coord}={sv!r}')
        print(' | '.join(parts))

print_range(ws_task, 10, 50, 1, 12, title='Task!A10:L50')

print('\nData first 12 rows, cols A:Z (non-empty cells only):')
for r in range(1, 13):
    parts = []
    for c in range(1, 27):
        v = ws_data.cell(r,c).value
        if v is None or v == '':
            continue
        coord = f'{get_column_letter(c)}{r}'
        sv = v
        if isinstance(sv, str) and len(sv) > 40:
            sv = sv[:37] + '...'
        parts.append(f'{coord}={sv!r}')
    if parts:
        print('Row', r, ':', ' | '.join(parts))

print('\nData! rows 21:38, cols A:Z (non-empty cells):')
for r in range(21, 39):
    parts = []
    for c in range(1, 27):
        v = ws_data.cell(r,c).value
        if v is None or v == '':
            continue
        coord = f'{get_column_letter(c)}{r}'
        sv = v
        if isinstance(sv, str) and len(sv) > 40:
            sv = sv[:37] + '...'
        parts.append(f'{coord}={sv!r}')
    if parts:
        print('Row', r, ':', ' | '.join(parts))
    else:
        print('Row', r, ': <all empty in A:Z>')

print('\nData rows 20-22 full A:Z (blanks shown as ".")')
for r in range(20, 23):
    row = []
    for c in range(1, 27):
        v = ws_data.cell(r,c).value
        if v is None or v == '':
            row.append('.')
        else:
            s = str(v)
            row.append(s if len(s)<=14 else s[:11]+'...')
    print(r, row)

wb.close()
print('\nInspection complete.')
